package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static com.bridge.quartercore.NativeSheetsModel.*;
class ManagedQuarterOverallRetentionTest {
 static final ManualQuarterMaintenance.Binding B=new ManualQuarterMaintenance.Binding(RecoveredFixture.ID,RecoveredFixture.DATASET,"bridgego-managed");
 static Book baseline()throws Exception{Book book=RecoveredFixture.book();book.sheet("dataset").rows.set(1,new ArrayList<>(List.of(B.purpose(),B.datasetId())));book.sheet("retention_ledger").rows.add(new ArrayList<>(List.of("2026-Q3","2026-06-30T16:00:00Z","COMPLETE","2026-06-30T16:00:01Z","1")));return NativeCommitJournal.bootstrap(B,book,NativeCommitJournal.digest(B,book),JournalQuarterProtocolTest.CLOCK).expected();}
 @Test void nativeAtomicFoldRetainsOverallAndLifetimeWhileRemovingOnlyExpiredRaw()throws Exception{var memory=new JournalQuarterProtocolTest.Memory(baseline());var before=memory.book.copy();var records=ManualQuarterMaintenance.decoded(before.tables());var expected=new com.bridge.persistence.QuarterlyOverallSummary.Summary(new com.bridge.persistence.QuarterlyOverallSummary.Counts(1,1,0,1,0,0),new com.bridge.persistence.QuarterlyOverallSummary.Counts(0,0,0,0,0,0));assertEquals(expected,QuarterlyOverallSummary.summarize("2026-Q3",records.values(),JournalQuarterProtocolTest.CLOCK.instant()));var protocol=new JournalQuarterProtocol(B,memory,JournalQuarterProtocolTest.CLOCK,"managed-overall");protocol.start();assertEquals(JournalQuarterProtocol.Status.VERIFIED,protocol.status());assertEquals(5,memory.writes);var rows=memory.book.sheet("quarterly_aggregates").rows;assertEquals(2,rows.size());assertEquals(QuarterlyOverallSummary.encodeRow("2026-Q3",expected),rows.get(1));assertEquals(List.of("2026-Q3","INTERNAL_COUNTS","{\"version\":2,\"FORMAL\":{\"matches\":1,\"completedDeals\":1,\"draws\":0,\"scoredMatches\":1,\"forfeitMatches\":0,\"interruptedMatches\":0},\"CASUAL\":{\"matches\":0,\"completedDeals\":0,\"draws\":0,\"scoredMatches\":0,\"forfeitMatches\":0,\"interruptedMatches\":0}}","","2"),rows.get(1));assertEquals(expected,QuarterlyOverallSummary.decodeRow(rows.get(1)).counts().orElseThrow());
  assertEquals(before.tables().get("quarterly_aggregates"),memory.states.get(1).tables().get("quarterly_aggregates"));var fold=memory.states.get(2);assertEquals(rows,fold.tables().get("quarterly_aggregates"));assertEquals(memory.book.tables().get("accounts"),fold.tables().get("accounts"));assertEquals(memory.book.tables().get("commits"),fold.tables().get("commits"));assertEquals(2,fold.tables().get("commits").size());for(int i=1;i<=2;i++){var row=memory.book.sheet("accounts").rows.get(i);assertEquals(before.sheet("accounts").rows.get(i).subList(0,4),row.subList(0,4));assertEquals(1,LifetimeStatistics.decode(row.get(4)).formal().matches());assertEquals(i==1?7:-3,LifetimeStatistics.decode(row.get(4)).formal().totalScore());assertEquals(0,LifetimeStatistics.decode(row.get(4)).casual().matches());}assertEquals(before.tables().get("auth_identities"),memory.book.tables().get("auth_identities"));
  for(var state:memory.states)assertDoesNotThrow(()->ManualQuarterMaintenance.validate(new ManualQuarterMaintenance.Snapshot(B.spreadsheetId(),true,state.tables()),B,JournalQuarterProtocolTest.CLOCK));assertThrows(RuntimeException.class,protocol::start);assertEquals(5,memory.writes);
 }
 @Test void followingQuarterPreservesFormalHistoryAndAddsKnownCasualInterruptedCounts()throws Exception{var memory=new JournalQuarterProtocolTest.Memory(baseline());var first=new JournalQuarterProtocol(B,memory,JournalQuarterProtocolTest.CLOCK,"managed-first");first.start();assertEquals(JournalQuarterProtocol.Status.VERIFIED,first.status());var formal=List.copyOf(memory.book.sheet("quarterly_aggregates").rows.get(1));var nextClock=java.time.Clock.fixed(java.time.Instant.parse("2027-01-01T00:00:00Z"),java.time.ZoneOffset.UTC);var next=new JournalQuarterProtocol(B,memory,nextClock,"managed-second");next.start();assertEquals(JournalQuarterProtocol.Status.VERIFIED,next.status());assertEquals(10,memory.writes);var rows=memory.book.sheet("quarterly_aggregates").rows;assertEquals(3,rows.size());assertEquals(formal,rows.get(1));assertEquals("2026-Q4",rows.get(2).get(0));var counts=QuarterlyOverallSummary.decodeRow(rows.get(2)).counts().orElseThrow();assertEquals(new com.bridge.persistence.QuarterlyOverallSummary.Counts(0,0,0,0,0,0),counts.formal());assertEquals(new com.bridge.persistence.QuarterlyOverallSummary.Counts(1,1,0,0,0,1),counts.casual());assertEquals(1,memory.book.sheet("commits").rows.size());assertEquals(1,memory.book.sheet("envelopes").rows.size());assertThrows(RuntimeException.class,next::start);assertEquals(10,memory.writes);}
 @Test void unknownAtomicFoldStopsAndNeverWritesAnotherPhaseOrDoubleCounts()throws Exception{var memory=new JournalQuarterProtocolTest.Memory(baseline());memory.failAt=3;memory.applyUnknown=true;var p=new JournalQuarterProtocol(B,memory,JournalQuarterProtocolTest.CLOCK,"managed-unknown");p.start();assertEquals(JournalQuarterProtocol.Status.REVIEW,p.status());assertEquals(3,memory.writes);assertEquals("INTERNAL_COUNTS",memory.book.sheet("quarterly_aggregates").rows.get(1).get(1));assertEquals(2,memory.book.sheet("commits").rows.size());assertThrows(RuntimeException.class,p::start);assertEquals(3,memory.writes);}
 @Test void duplicateSummaryAndMalformedV2FailBeforeFold()throws Exception{for(boolean malformed:List.of(false,true)){Book book=baseline();var summary=QuarterlyOverallSummary.summarize("2026-Q3",ManualQuarterMaintenance.decoded(book.tables()).values(),JournalQuarterProtocolTest.CLOCK.instant());book.sheet("quarterly_aggregates").rows.add(new ArrayList<>(QuarterlyOverallSummary.encodeRow("2026-Q3",summary)));if(malformed)book.sheet("quarterly_aggregates").rows.get(1).set(2,"{}");else book.sheet("quarterly_aggregates").rows.add(new ArrayList<>(book.sheet("quarterly_aggregates").rows.get(1)));assertThrows(RuntimeException.class,()->ManualQuarterMaintenance.validate(new ManualQuarterMaintenance.Snapshot(B.spreadsheetId(),true,book.tables()),B,JournalQuarterProtocolTest.CLOCK));}}
 @Test void oldSuppressedMeansUnavailableAndIsolatedEPolicyRemainsSuppressed()throws Exception{assertTrue(QuarterlyOverallSummary.decodeRow(List.of("2026-Q3","SUPPRESSED","","","1")).counts().isEmpty());var memory=new JournalQuarterProtocolTest.Memory(JournalQuarterProtocolTest.baseline());var p=JournalQuarterProtocolTest.protocol(memory);p.start();assertEquals(JournalQuarterProtocol.Status.VERIFIED,p.status());assertEquals("SUPPRESSED",memory.book.sheet("quarterly_aggregates").rows.get(1).get(1));assertFalse(QuarterlyRetention.AggregatePolicy.suppressAll().internalCounts());assertFalse(new QuarterlyRetention.AggregatePolicy(true,50,20,10).internalCounts());}
}
